package com.nigson.experience.notification;

import static org.assertj.core.api.Assertions.*;
import com.nimbusds.jose.*;import com.nimbusds.jose.crypto.*;import com.nimbusds.jose.jwk.*;import com.nimbusds.jwt.*;
import com.nigson.experience.ExperienceApplication;import com.nigson.shared.events.EventCodec;import com.sun.net.httpserver.HttpServer;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.interfaces.*;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.springframework.boot.builder.SpringApplicationBuilder;import org.springframework.boot.web.server.context.WebServerApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;

class NotificationHttpTest {
 @Test void actualHttpRequiresExactWorkloadAndPersistsOwnerCheckedMonotonicOutcome()throws Exception{
  String jdbcUrl=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(jdbcUrl!=null,"API-137 HTTP acceptance requires native PostgreSQL");var gen=KeyPairGenerator.getInstance("RSA");gen.initialize(2048);var rsa=gen.generateKeyPair();var ecGen=KeyPairGenerator.getInstance("EC");ecGen.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));var ec=ecGen.generateKeyPair();var jwks=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String issuer="http://127.0.0.1:"+jwks.getAddress().getPort()+"/realms/offline";jwks.createContext("/",x->{byte[] body=EventCodec.JSON.writeValueAsBytes(Map.of("keys",List.of(new com.nimbusds.jose.jwk.RSAKey.Builder((RSAPublicKey)rsa.getPublic()).keyID("synthetic").algorithm(JWSAlgorithm.RS256).keyUse(KeyUse.SIGNATURE).build().toJSONObject())));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,body.length);x.getResponseBody().write(body);x.close();});jwks.start();
  byte[] testKey=new byte[32],cipherKey=new byte[32];Arrays.fill(testKey,(byte)5);Arrays.fill(cipherKey,(byte)6);var props=new HashMap<String,Object>();props.put("APP_ENV","test");props.put("NIGSON_SECURITY_ENABLED","true");props.put("NIGSON_PRODUCT_PHASE","1");props.put("NIGSON_EVENTS_ENABLED","false");props.put("NIGSON_JDBC_URL",jdbcUrl+"?currentSchema=experience");props.put("NIGSON_DB_USER","nigson_experience_app");props.put("NIGSON_DB_PASSWORD","mock-experience-runtime");props.put("NIGSON_OIDC_ISSUER",issuer);props.put("NIGSON_OIDC_JWKS",issuer+"/protocol/openid-connect/certs");props.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");props.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",Base64.getEncoder().encodeToString(ec.getPublic().getEncoded()))));props.put("NIGSON_MESSAGING_INBOUND_ENABLED","true");props.put("NIGSON_PHONE_CIPHER_REVISION","synthetic");props.put("NIGSON_PHONE_HASH_KEY_VERSION","1");props.put("NIGSON_PHONE_LOCAL_HASH_KEY",Base64.getEncoder().encodeToString(testKey));props.put("NIGSON_PHONE_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(cipherKey));props.put("NIGSON_INBOUND_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(cipherKey));props.put("NIGSON_INBOUND_RETENTION_DAYS","30");props.put("NIGSON_TWILIO_ACCOUNT_SID","AC0123456789abcdef0123456789abcdef");props.put("NIGSON_TWILIO_AUTH_TOKEN","synthetic-never-live-auth-token-long-enough");props.put("NIGSON_TWILIO_WHATSAPP_FROM","whatsapp:+2348031234567");props.put("NIGSON_TWILIO_WHATSAPP_PUBLIC_URL","https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp");props.put("NIGSON_LEAD_RECIPIENT_GROUP","synthetic-sales-triage");props.put("server.port","0");props.put("logging.level.root","WARN");
  try(var app=new SpringApplicationBuilder(ExperienceApplication.class).properties(props).run();var http=HttpClient.newHttpClient()){
   String base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort(),path="/internal/v1/notification-deliveries";JdbcTemplate jdbc=app.getBean(JdbcTemplate.class);UUID resource=UUID.randomUUID(),job=UUID.randomUUID();jdbc.update("INSERT INTO experience.lead(id,created_by,updated_by,type,name,email,subject,message,status,source) VALUES (?, 'notification-http','notification-http','CONTACT','Synthetic','synthetic@example.invalid','Notification HTTP fixture','fixture','NEW','WEB')",resource);
   String workload=workload(rsa,issuer,"nigson-integration","notification.write"),body=EventCodec.JSON.writeValueAsString(Map.of("jobId",job,"resourceId",resource,"state","UNKNOWN")),key=UUID.randomUUID().toString();var missing=send(http,base+path,body,null,key);assertThat(missing.statusCode()).isIn(401,403);var wrong=send(http,base+path,body,workload(rsa,issuer,"nigson-integration","notification.read"),UUID.randomUUID().toString());assertThat(wrong.statusCode()).isIn(401,403);
   var response=send(http,base+path,body,workload,key);assertThat(response.statusCode()).withFailMessage(response.body()).isEqualTo(200);assertThat(response.headers().firstValue("Cache-Control")).contains("no-store");assertThat(EventCodec.JSON.readTree(response.body()).path("acknowledged").asBoolean()).isTrue();assertThat(send(http,base+path,body,workload,key).body()).isEqualTo(response.body());assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE action='NOTIFICATION_DELIVERY' AND resource_id=?",Long.class,job)).isEqualTo(1);
   UUID other=UUID.randomUUID();String forged=EventCodec.JSON.writeValueAsString(Map.of("jobId",UUID.randomUUID(),"resourceId",other,"state","FAILED"));var notFound=send(http,base+path,forged,workload,UUID.randomUUID().toString());assertThat(notFound.statusCode()).isEqualTo(404);String sent=body.replace("UNKNOWN","SENT");assertThat(send(http,base+path,sent,workload,UUID.randomUUID().toString()).statusCode()).isEqualTo(200);assertThat(send(http,base+path,body,workload,UUID.randomUUID().toString()).statusCode()).isEqualTo(409);
   String extra=body.substring(0,body.length()-1)+",\"unexpected\":true}";assertThat(send(http,base+path,extra,workload,UUID.randomUUID().toString()).statusCode()).isEqualTo(400);
  }finally{jwks.stop(0);}
 }
 private static String workload(KeyPair rsa,String issuer,String client,String scope)throws Exception{var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("synthetic").build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-workload").audience("nigson-experience").claim("typ","Bearer").claim("client_id",client).claim("azp",client).claim("scope",scope).issueTime(new Date()).expirationTime(Date.from(Instant.now().plusSeconds(120))).build());jwt.sign(new RSASSASigner((RSAPrivateKey)rsa.getPrivate()));return jwt.serialize();}
 private static HttpResponse<String> send(HttpClient http,String url,String body,String bearer,String key)throws Exception{var b=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("X-Correlation-ID",UUID.randomUUID().toString()).header("Idempotency-Key",key).header("Content-Type","application/json");if(bearer!=null)b.header("Authorization","Bearer "+bearer);return http.send(b.POST(HttpRequest.BodyPublishers.ofString(body,StandardCharsets.UTF_8)).build(),HttpResponse.BodyHandlers.ofString());}
}
